using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Analysis;

internal sealed class ConcreteCoefficientSeriesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Analysis/ConcreteCoefficientSeries.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual square-summable coefficient series equal the norm-closed complex coefficient span in the inherited continuous-dual norm.",
        H("Standard concrete coefficient series"), Blocks(
            Paragraph(Text("H is any complete complex Hilbert space and M is an actual concrete von Neumann algebra on H. No separability, countable dimension or nonzero-space assumption is imposed. The functional norm is the norm inherited from StrongDual C M.toStarSubalgebra. E denotes ConcreteCoefficientPredual.coefficientSpace M, already defined as the norm closure of the complex span of restricted vector coefficients.")),
            Node("IsCoefficientSeries", "An independent concrete source class",
                "A continuous complex-linear functional phi belongs to IsCoefficientSeries M precisely when there are sequences xi,eta:N->H with sum ||xi(n)|| squared finite and sum ||eta(n)|| squared finite, and phi(a)=sum_n <xi(n),a eta(n)> for every actual a in M. This definition uses actual countable series and does not mention E, intrinsic order normality, or an abstract chosen predual.", false),
            Node("series_mem_coefficientSpace", "Series converge in the actual dual norm",
                "Every independently specified coefficient series belongs to E. Young's inequality makes sum ||xi(n)|| ||eta(n)|| finite. The coefficient norm bound gives absolute norm convergence in the actual continuous dual. Evaluation of this sum agrees with the specified functional on every a, and E is closed."),
            Node("series_order_normal", "The forward intrinsic-normal interface",
                "Every standard coefficient-series functional is intrinsically order-normal on M. This consumes series_mem_coefficientSpace and the proved all-directed coefficientSpace_le_normalDual interface. It is used by StandardL1Preparation.toNormal; no converse is asserted."),
            Node("dual_evaluation", "Isometric concrete representation of E-star",
                "For every bounded complex-linear Lambda:E->C there exists an actual a in M such that Lambda(phi)=phi(a) for every phi in E and ||a||=||Lambda||. Extend Lambda with unchanged norm to the ambient dual. Riesz representation of the vector coefficient form produces T, and the represented operator is T.adjoint with the stated inner-product convention. Coefficient identities force this operator to commute with every member of M's commutant. The bicommutant identity puts it in M. Agreement extends from coefficients through their span and norm closure. The coefficient norm estimate and operator norm characterization give equality of the actual norms."),
            Node("closure_convex_coefficientBall", "The actual unit ball is generated by coefficient budgets",
                "Let coefficientBall be the E-elements represented by one coefficient <xi,a eta> with ||xi|| ||eta||<=1. The norm closure of its REAL convex hull equals the actual closed unit ball of E. A strict complex geometric Hahn-Banach separator would be evaluation at an actual a in M by dual_evaluation. Its bound on all budgeted coefficients bounds ||a|| and hence its value on the purported separated unit vector, a contradiction. The reverse inclusion is the coefficient norm estimate and convex closedness."),
            Node("coefficientSpace_series", "Constructing actual countable standard series",
                "Every phi in E has an actual square-summable coefficient-series representation. Unit-ball density supplies finite layers of product budget at most the current residual norm and residual error at most half that norm. Balance each vector pair so both squared norms equal its product cost, with zero terms handled separately. Iterate the residual construction; the residual norms are bounded by (1/2)^n ||phi||. Both squared-norm sums over the countable sigma of finite layers are finite. Absolute dual-norm convergence and telescoping identify the sum with phi. Encode that countable sigma into N and extend both vectors by zero, preserving both square sums and every actual coefficient value. No trace-class duality or optimal nuclear constant is assumed."),
            Node("mem_coefficientSpace_iff_series", "Exact equality of the independent classes",
                "For every actual continuous complex-linear phi on M, membership in the norm-closed complex coefficient span E is equivalent to IsCoefficientSeries M phi. This exact equivalence is consumed to put the original realized whole-L1 map, and its lifted original source, in the standard concrete predual class. It does not prove the full converse from arbitrary intrinsic order-normal functionals or Sakai uniqueness."),
            Paragraph(Text("These classical coefficient-space and Hilbert-space arguments supply the standard-source bridge for the arbitrary-convex reverse-test endpoint. They are not presented as separate solved conjectures or as a worldwide-priority claim. The owning divergence module retains the exact source class, literal extended costs, and the unchanged whole-L1 realization."))
        )));

    private static DocumentBlock Node(string name, string heading, string prose, bool theorem = true) =>
        Describe.Lean(DescribeId.Create("concrete-coefficient-series-" + name.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(heading), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))),
            theorem ? DescribeRole.Theorem : DescribeRole.Definition);
}
